import { ApiProperty } from '@nestjs/swagger';
import { IsInt, IsString, Max, Min, MinLength } from 'class-validator';

export class CreateUserDto {
  @ApiProperty({
    example: 'Alice',
    minLength: 2,
    description: '用户名称',
  })
  @IsString()
  @MinLength(2)
  name: string;

  @ApiProperty({
    example: 20,
    minimum: 1,
    maximum: 120,
    description: '用户年龄',
  })
  @IsInt()
  @Min(1)
  @Max(120)
  age: number;
}

import { PartialType } from '@nestjs/swagger';
import { CreateUserDto } from './create-user.dto';

export class UpdateUserDto extends PartialType(CreateUserDto) {}

import { PickType } from '@nestjs/swagger';
import { UpdateNoteDto } from './update-note.dto';

export class UpdateNoteTitleDto extends PickType(UpdateNoteDto, ['title'] as const) {}

import { Type } from 'class-transformer';
import { IsInt, IsOptional, IsString, Max, Min } from 'class-validator';

export class FindUsersQueryDto {
  @IsOptional()
  @IsString()
  keyword?: string;

  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  page = 1;

  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  @Max(100)
  pageSize = 10;
}

import { FindUsersQueryDto } from './dto/find-users-query.dto';

@Get()
findAll(@Query() query: FindUsersQueryDto) {
  return this.usersService.findAll(query);
}

import { FindUsersQueryDto } from './dto/find-users-query.dto';

findAll(query: FindUsersQueryDto) {
  const keyword = query.keyword?.trim().toLowerCase();
  const filteredUsers = keyword
    ? this.users.filter((user) => user.name.toLowerCase().includes(keyword))
    : this.users;

  const page = query.page ?? 1;
  const pageSize = query.pageSize ?? 10;
  const start = (page - 1) * pageSize;
  const items = filteredUsers.slice(start, start + pageSize);

  return {
    items,
    page,
    pageSize,
    total: filteredUsers.length,
  };
}

@Type(() => Number)
  告诉 class-transformer 把 query 字符串转换成 number

@IsInt / @Min / @Max
  告诉 class-validator 转换后要满足什么规则

import { ValidationPipe } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);

  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      forbidNonWhitelisted: true,
      transform: true,
    }),
  );

  const swaggerConfig = new DocumentBuilder()
    .setTitle('Notes API')
    .setDescription('NestJS learning project API')
    .setVersion('week-3')
    .build();

  const swaggerDocument = SwaggerModule.createDocument(app, swaggerConfig);
  SwaggerModule.setup('api-docs', app, swaggerDocument);

  const port = process.env.PORT ?? 3000;

  await app.listen(port);
  console.log(`Nest learning API is running on http://localhost:${port}`);
}

void bootstrap();

import { ApiTags } from '@nestjs/swagger';

@ApiTags('users')
@Controller('users')
export class UsersController {}

import { ApiTags } from '@nestjs/swagger';

@ApiTags('notes')
@Controller('notes')
export class NotesController {}

import { BadRequestException, Injectable, PipeTransform } from '@nestjs/common';

@Injectable()
export class ParseIdPipe implements PipeTransform<string, number> {
  transform(value: string) {
    const parsedValue = Number(value);

    if (!Number.isInteger(parsedValue) || parsedValue <= 0) {
      throw new BadRequestException('id must be a positive integer');
    }

    return parsedValue;
  }
}

it('/users creates a user', () => {
  return request(app.getHttpServer())
    .post('/users')
    .send({ name: 'Charlie', age: 24 })
    .expect(201);
});

it('/users rejects invalid body', () => {
  return request(app.getHttpServer())
    .post('/users')
    .send({ name: 'C', age: 24 })
    .expect(400);
});

it('/users/:id returns 404 when user does not exist', () => {
  return request(app.getHttpServer()).get('/users/999').expect(404);
});

it('/users rejects invalid pagination query', () => {
  return request(app.getHttpServer()).get('/users?page=0').expect(400);
});
